  logic unused_assert_connected;

    initial begin                                                                      
    
    
    
    #1ps;                                                                            
    AssertConnected_A: assert (unused_assert_connected === 1'b1 || !EnableAlertTriggerSVA)                                                          
      else begin                                                                     
        $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_count_0/rtl/prim_count.sv", 5,         
         "AssertConnected_A");                                                       
                                                        
      end                                                                            
  end                                                                                



